// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/readyz", wrapper.Ready)
	m.HandleFunc("POST "+options.BaseURL+"/v1/barriers", wrapper.AcquireBarrier)
	m.HandleFunc("POST "+options.BaseURL+"/v1/barriers/{barrierId}:release", wrapper.ReleaseBarrier)
	m.HandleFunc("GET "+options.BaseURL+"/v1/glossary", wrapper.ListGlossary)
	m.HandleFunc("POST "+options.BaseURL+"/v1/glossary-batches/{batchId}:rollback", wrapper.RollbackAutomaticGlossaryBatch)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/glossary/{termId}", wrapper.DeleteGlossaryTerm)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/glossary/{termId}", wrapper.PutGlossaryTerm)
	m.HandleFunc("POST "+options.BaseURL+"/v1/glossary:apply-approved-proposal", wrapper.ApplyApprovedGlossaryProposal)
	m.HandleFunc("GET "+options.BaseURL+"/v1/interface-strings/{language}", wrapper.ReadInterfaceCatalog)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/interface-strings/{language}/{key}", wrapper.PutInterfaceString)
	m.HandleFunc("POST "+options.BaseURL+"/v1/interface-strings/{language}:translate", wrapper.RequestInterfaceTranslation)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/language-preferences", wrapper.SaveLanguagePreference)
	m.HandleFunc("GET "+options.BaseURL+"/v1/language-suggestion-approvals/{approvalId}", wrapper.ReadLanguageSuggestionApproval)
	m.HandleFunc("GET "+options.BaseURL+"/v1/language-suggestion-policy", wrapper.ReadLanguageSuggestionPolicy)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/language-suggestion-policy", wrapper.PutLanguageSuggestionPolicy)
	m.HandleFunc("POST "+options.BaseURL+"/v1/language-suggestions", wrapper.SuggestLanguage)
	m.HandleFunc("GET "+options.BaseURL+"/v1/languages", wrapper.ListLanguages)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/languages/{tag}", wrapper.PutLanguage)
	m.HandleFunc("POST "+options.BaseURL+"/v1/languages/{tag}/enabled", wrapper.SetLanguageEnabled)
	m.HandleFunc("POST "+options.BaseURL+"/v1/languages/{tag}:approve-plan", wrapper.ApproveLanguagePlan)
	m.HandleFunc("POST "+options.BaseURL+"/v1/languages/{tag}:estimate", wrapper.EstimateLanguagePlan)
	m.HandleFunc("GET "+options.BaseURL+"/v1/snapshots/{snapshotId}/archive", wrapper.ReadSnapshotArchive)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:discard", wrapper.DiscardSnapshot)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:export", wrapper.ExportSnapshot)
	m.HandleFunc("POST "+options.BaseURL+"/v1/snapshots:stage", wrapper.StageSnapshot)
	m.HandleFunc("GET "+options.BaseURL+"/v1/translation-titles", wrapper.ListTranslationTitles)
	m.HandleFunc("POST "+options.BaseURL+"/v1/translations", wrapper.CreateTranslation)
	m.HandleFunc("GET "+options.BaseURL+"/v1/translations/progress", wrapper.ListTranslationProgress)
	m.HandleFunc("POST "+options.BaseURL+"/v1/translations/{translationId}/cancel", wrapper.CancelTranslation)
	m.HandleFunc("GET "+options.BaseURL+"/v1/translations/{translationId}/units", wrapper.ReadTranslationUnits)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/translations/{translationId}/units/{unitId}", wrapper.EditTranslationUnit)
	m.HandleFunc("POST "+options.BaseURL+"/v1/translations/{translationId}/units/{unitId}/protection", wrapper.SetUnitProtection)
	m.HandleFunc("POST "+options.BaseURL+"/v1/translations:read", wrapper.ReadTranslation)

	return m
}

